#!/bin/bash
# Fusion stage decomposition follow-up (user: backbone / neck / head analysis): which consistency scalars the CURRENT post-processing (F8K
# steps: VBxhe10 + li2 + kw2) still fails to transfer from the heads, on 150 seeded VT shots (paired arms, one shared inference), newest
# TRAIN-only heads in F8's proportions. Arms: VBxhe10 (pre-F7 steps), F8K, F8K + 2 extra li passes. Then stage_decomp.py per arm.
cd /home/mohhakami/Documents/paper/quworld; export CUDA_VISIBLE_DEVICES=0 PYTHONUNBUFFERED=1; LOG=runs/strat/fusion/s44_transfer_vt.log
env QW_GPU_GB=30 runs/capped.sh s44vt 40 .venv/bin/python paper/strat/fusion/gpu_build.py --split vt --tag S44T --psi psiF --psis "PQmix~g" \
  --guard psiF:0.25 --qb qh50 --qbheads "head_qb_QH_s1+head_qb_QH_s2+head_qb_QH_s3+head_qb_QH_s4+head_qb_QH_s5+head_qb_QH_s6" --heads "head_boundary_v8_J1RL_s1*3+head_boundary_v8_J1QPIpi_s1+head_boundary_v8_J1QPIpi_s2+head_boundary_v8_J1QH_s1+head_boundary_v8_J1QH_s2+head_boundary_v8_J1QH_s3" --xpheads head_xp_XP1_s1+head_xp_XP1_s2+head_xp_XP1_s3 --kws '{"VBxhe10": {"_steps": ["shift", "bw", "xhe", "kw", "xp", "jgn", "li"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "F8K": {"_steps": ["shift", "bw", "xhe", "kw", "xp", "jgn", "li", "li2", "kw2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}, "F8Kli4": {"_steps": ["shift", "bw", "xhe", "kw", "xp", "jgn", "li", "li2", "kw2", "li2", "li2"], "xp": {"sigma": 0.15, "cap": 0.1}, "li": {"cap": 0.9}, "xhe": {"gate": 0.01}}}' --axis head \
  --qbclamp --vt-shots "45,54,56,67,76,157,258,317,343,388,554,610,667,698,739,753,765,813,902,931,964,975,1001,1026,1152,1153,1198,1208,1223,1389,1407,1436,1489,1531,1568,1572,1577,1626,1628,1698,1959,1991,2052,2097,2237,2256,2288,2359,2444,2452,2534,2564,2581,2596,2608,2616,2674,2686,2703,2716,2765,2796,2939,2960,2986,2987,3012,3026,3028,3073,3124,3205,3206,3225,3365,3378,3420,3468,3470,3643,3644,3661,3769,3796,3797,3805,3843,3863,3881,3901,4018,4047,4119,4154,4160,4188,4270,4278,4316,4340,4490,4542,4566,4636,4646,4669,4706,4736,4767,4798,4845,4867,5023,5062,5131,5140,5259,5310,5390,5491,5668,5687,5734,5833,5897,5899,5938,6003,6081,6118,6174,6199,6218,6253,6287,6312,6314,6530,6566,6609,6615,6682,6686,6787,6791,6822,6872,6935,6983,7005" >> $LOG 2>&1 || { echo "CRASH s44 vt $(date -Is)" >> $LOG; exit 1; }
for arm in VBxhe10 F8K F8Kli4; do
  .venv/bin/python runs/strat/fusion/stage_decomp.py "PQmix~g_ns" "PQmix~g_$arm" J1RL_s1,J1RL_s1,J1RL_s1,J1QPIpi_s1,J1QPIpi_s2,J1QH_s1,J1QH_s2,J1QH_s3 >> $LOG 2>&1
done
echo "S44_TRANSFER_DONE $(date -Is)" >> $LOG
